    const expected = [_]u64{1};
    const coins = [_]u64{ 1, 5, 10, 25 };
    const actual = try change.findFewestCoins(testing.allocator, &coins, 1);
    defer testing.allocator.free(actual);
    try testing.expectEqualSlices(u64, &expected, actual);
